use rusqlite::Transaction;

pub(crate) fn apply(t: &Transaction<'_>, c: u32) -> rusqlite::Result<()> {
    if c < 2 {
        t.execute_batch("CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, title TEXT NOT NULL, workspace_path TEXT NOT NULL, source_ref TEXT, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))); CREATE TABLE IF NOT EXISTS work_items (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), parent_id TEXT REFERENCES work_items(id), title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', source_ref TEXT, acceptance_criteria TEXT NOT NULL DEFAULT '', non_goals TEXT NOT NULL DEFAULT '', status TEXT NOT NULL CHECK(status IN ('backlog','ready','in_progress','done')), priority INTEGER NOT NULL DEFAULT 0, estimate INTEGER, complexity TEXT, attempt_count INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))); CREATE TABLE IF NOT EXISTS work_item_edges (from_work_item_id TEXT NOT NULL REFERENCES work_items(id) ON DELETE CASCADE, to_work_item_id TEXT NOT NULL REFERENCES work_items(id) ON DELETE CASCADE, kind TEXT NOT NULL, PRIMARY KEY(from_work_item_id, to_work_item_id, kind)); CREATE TABLE IF NOT EXISTS provenance (id TEXT PRIMARY KEY, kind TEXT NOT NULL, source TEXT NOT NULL, payload BLOB NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))); CREATE TABLE IF NOT EXISTS runs (id TEXT PRIMARY KEY, work_item_id TEXT NOT NULL REFERENCES work_items(id), status TEXT NOT NULL, policy_snapshot BLOB NOT NULL, role_snapshot BLOB NOT NULL, skill_snapshot BLOB NOT NULL, model_route_snapshot BLOB NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))); CREATE TABLE IF NOT EXISTS command_dedup (client_id TEXT NOT NULL, request_id TEXT NOT NULL, command_hash TEXT NOT NULL, result BLOB NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), PRIMARY KEY(client_id, request_id)); PRAGMA user_version = 2;")?;
    }
    Ok(())
}
